CREATE TABLE IF NOT EXISTS stores(id SERIAL PRIMARY KEY,name TEXT NOT NULL,address TEXT DEFAULT '',login_code TEXT NOT NULL,manager_name TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,store_id INTEGER REFERENCES stores(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('store','ops','admin')),password_hash TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS report_fields(id SERIAL PRIMARY KEY,label TEXT NOT NULL,key TEXT NOT NULL UNIQUE,field_type TEXT NOT NULL DEFAULT 'number',unit TEXT DEFAULT '',required BOOLEAN NOT NULL DEFAULT false,sort_order INTEGER NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS daily_reports(id SERIAL PRIMARY KEY,store_id INTEGER NOT NULL REFERENCES stores(id) ON DELETE CASCADE,report_date DATE NOT NULL,submitted_by INTEGER REFERENCES users(id) ON DELETE SET NULL,payload JSONB NOT NULL DEFAULT '{}',version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(store_id,report_date));
CREATE TABLE IF NOT EXISTS monthly_goals(id SERIAL PRIMARY KEY,store_id INTEGER NOT NULL REFERENCES stores(id) ON DELETE CASCADE,month TEXT NOT NULL,goal_type TEXT NOT NULL,goal_value NUMERIC NOT NULL,rule TEXT NOT NULL DEFAULT 'average',created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(store_id,month,goal_type));
CREATE TABLE IF NOT EXISTS tasks(id SERIAL PRIMARY KEY,store_id INTEGER NOT NULL REFERENCES stores(id) ON DELETE CASCADE,goal_id INTEGER REFERENCES monthly_goals(id) ON DELETE CASCADE,title TEXT NOT NULL,target_value NUMERIC NOT NULL,unit TEXT DEFAULT '',task_date DATE NOT NULL,actual_value NUMERIC DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(store_id,goal_id,task_date));
CREATE TABLE IF NOT EXISTS issues(id SERIAL PRIMARY KEY,store_id INTEGER REFERENCES stores(id) ON DELETE CASCADE,submitter_name TEXT NOT NULL,type TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',handler_id INTEGER REFERENCES users(id) ON DELETE SET NULL,handled_at TIMESTAMPTZ,handling_note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,detail JSONB DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
